import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { Plugin } from 'vite';

/** Where the notices land in the built app; About links to it, and desktop release builds bundle it. */
export const THIRD_PARTY_NOTICES_FILE = 'third-party-notices.txt';

/**
 * Adds the third-party notices to every build (never to the dev server), generated by scripts/third-party-notices.mjs
 * from the dependency graphs. A failed generation, such as a shipped package without license text, fails the build.
 */
export function thirdPartyNoticesPlugin(repoRoot: string): Plugin {
  return {
    name: 'pushform-third-party-notices',
    apply: 'build',
    generateBundle() {
      const dir = mkdtempSync(join(tmpdir(), 'pushform-notices-'));
      try {
        const out = join(dir, THIRD_PARTY_NOTICES_FILE);
        try {
          execFileSync(process.execPath, [join(repoRoot, 'scripts/third-party-notices.mjs'), '--out', out], { stdio: 'inherit' });
        } catch {
          this.error('Generating the third-party notices failed (see the messages above).');
        }
        this.emitFile({ type: 'asset', fileName: THIRD_PARTY_NOTICES_FILE, source: readFileSync(out, 'utf8') });
      } finally {
        rmSync(dir, { recursive: true, force: true });
      }
    },
  };
}
